package com.rikkeibank.notification.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"transactionId","eventStatus"}))public class Notification{@Id private UUID id;@Column(nullable=false)private UUID customerId;@Column(nullable=false)private UUID transactionId;@Column(nullable=false)private String eventStatus;@Column(nullable=false,length=1000)private String message;@Column(nullable=false)private boolean readFlag;private Instant createdAt;protected Notification(){}public Notification(UUID c,UUID t,String s,String m){id=UUID.randomUUID();customerId=c;transactionId=t;eventStatus=s;message=m;createdAt=Instant.now();}public void markRead(){readFlag=true;}public UUID getId(){return id;}public UUID getCustomerId(){return customerId;}public UUID getTransactionId(){return transactionId;}public String getEventStatus(){return eventStatus;}public String getMessage(){return message;}public boolean isReadFlag(){return readFlag;}public Instant getCreatedAt(){return createdAt;}}

